CREATE TABLE public.business_search_consents(workspace_id uuid PRIMARY KEY REFERENCES public.workspaces(id), signed_in_enabled boolean NOT NULL DEFAULT false, public_enabled boolean NOT NULL DEFAULT false, signed_in_person_mfn_id text, public_person_mfn_id text, signed_in_changed_at timestamptz, public_changed_at timestamptz);
GRANT SELECT ON public.business_search_consents TO authenticated; GRANT ALL ON public.business_search_consents TO service_role;
ALTER TABLE public.business_search_consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_consent_manager_read ON public.business_search_consents FOR SELECT TO authenticated USING(public.can_manage_account_connections(workspace_id));
ALTER TABLE public.provider_network_profiles ADD COLUMN facility_category text, ADD COLUMN contact_email_public boolean NOT NULL DEFAULT false, ADD COLUMN contact_phone_public boolean NOT NULL DEFAULT false;
COMMENT ON TABLE public.provider_network_profiles IS 'Shared business identity for eligible Provider and Facility workspaces; audience consent is separate in business_search_consents. Private provider evidence remains protected.';
COMMENT ON COLUMN public.provider_network_profiles.visible IS 'DEPRECATED for search consent: use independently audited business_search_consents. No existing visibility is inferred as consent.';
CREATE POLICY facility_identity_manager_read ON public.provider_network_profiles FOR SELECT TO authenticated USING(public.can_manage_account_connections(workspace_id) AND EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=workspace_id AND w.account_type IN ('facility','hospital')));
CREATE FUNCTION public.set_business_search_consent(_ws uuid,_audience text,_enabled boolean,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person text;account text; BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true OR _audience NOT IN ('signed_in','public') OR _enabled IS NULL OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('provider','facility','hospital')) THEN RAISE EXCEPTION 'Visibility change unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 SELECT mfn_id INTO person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO account FROM public.workspaces WHERE id=_ws;
 INSERT INTO public.business_search_consents(workspace_id) VALUES(_ws) ON CONFLICT DO NOTHING;
 IF _audience='signed_in' THEN UPDATE public.business_search_consents SET signed_in_enabled=_enabled,signed_in_person_mfn_id=person,signed_in_changed_at=now() WHERE workspace_id=_ws;
 ELSE UPDATE public.business_search_consents SET public_enabled=_enabled,public_person_mfn_id=person,public_changed_at=now() WHERE workspace_id=_ws; END IF;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,'business_search_consent',auth.uid(),person,account,jsonb_build_object('audience',_audience,'enabled',_enabled)); END $$;
REVOKE ALL ON FUNCTION public.set_business_search_consent(uuid,text,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_business_search_consent(uuid,text,boolean,boolean) TO authenticated;
CREATE FUNCTION public.save_shared_business_identity(_ws uuid,_city text,_description text,_category text,_email text,_phone text,_email_public boolean,_phone_public boolean,_accepting boolean,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('provider','facility','hospital')) OR length(_city)>100 OR length(_description)>2000 OR length(_category)>100 OR length(_email)>254 OR length(_phone)>32 THEN RAISE EXCEPTION 'Business identity unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 INSERT INTO public.provider_network_profiles(workspace_id,location_city,description,facility_category,business_contact_email,business_contact_phone,contact_email_public,contact_phone_public,accepting_connections) VALUES(_ws,nullif(trim(_city),''),nullif(trim(_description),''),nullif(trim(_category),''),nullif(trim(_email),''),nullif(trim(_phone),''),_email_public,_phone_public,_accepting) ON CONFLICT(workspace_id) DO UPDATE SET location_city=excluded.location_city,description=excluded.description,facility_category=excluded.facility_category,business_contact_email=excluded.business_contact_email,business_contact_phone=excluded.business_contact_phone,contact_email_public=excluded.contact_email_public,contact_phone_public=excluded.contact_phone_public,accepting_connections=excluded.accepting_connections;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) SELECT _ws,'business_identity_confirmed',auth.uid(),p.mfn_id,w.mfn_id,jsonb_build_object('email_public',_email_public,'phone_public',_phone_public) FROM public.user_profiles p,public.workspaces w WHERE p.user_id=auth.uid() AND w.id=_ws; END $$;
REVOKE ALL ON FUNCTION public.save_shared_business_identity(uuid,text,text,text,text,text,boolean,boolean,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_shared_business_identity(uuid,text,text,text,text,text,boolean,boolean,boolean,boolean) TO authenticated;
CREATE FUNCTION public.search_business_identities(_audience text,_search text DEFAULT '') RETURNS TABLE(workspace_id uuid,business_name text,mfn_id text,business_type text,location text,description text,facility_category text,service_types text[],counties text[],cities text[],medical_delivery boolean,accepting_connections boolean,business_contact_email text,business_contact_phone text,verification_level text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT w.id,w.display_name,w.mfn_id,CASE WHEN w.account_type='provider' THEN 'provider' ELSE 'facility' END,coalesce(p.location_city,array_to_string(p.cities,', ')),p.description,p.facility_category,CASE WHEN w.account_type='provider' THEN p.service_types ELSE '{}'::text[] END,p.counties,p.cities,p.medical_delivery,p.accepting_connections,CASE WHEN p.contact_email_public THEN p.business_contact_email END,CASE WHEN p.contact_phone_public THEN p.business_contact_phone END,CASE WHEN w.account_type='provider' AND w.automatic_verification_level IN ('semi','super') THEN w.automatic_verification_level ELSE NULL END
 FROM public.workspaces w JOIN public.provider_network_profiles p ON p.workspace_id=w.id JOIN public.business_search_consents c ON c.workspace_id=w.id
 WHERE w.account_type IN ('provider','facility','hospital') AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles u ON u.user_id=m.user_id WHERE m.workspace_id=w.id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.status='active' AND NOT u.is_test_account AND u.deleted_at IS NULL)
 AND ((_audience='public' AND c.public_enabled) OR (_audience='signed_in' AND c.signed_in_enabled AND EXISTS(SELECT 1 FROM public.user_profiles u WHERE u.user_id=auth.uid() AND u.status='active' AND NOT u.is_test_account AND u.deleted_at IS NULL))) AND length(coalesce(_search,''))<=200 AND (coalesce(_search,'')='' OR w.display_name ILIKE '%'||_search||'%') ORDER BY w.display_name LIMIT 200 $$;
REVOKE ALL ON FUNCTION public.search_business_identities(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.search_business_identities(text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.search_connection_businesses(_ws uuid,_mode text,_value text) RETURNS TABLE(workspace_id uuid,business_name text,mfn_id text,business_type text,location text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR length(_value)<2 OR length(_value)>254 OR _mode NOT IN ('name','email','phone') THEN RAISE EXCEPTION 'Business search unavailable'; END IF;
 RETURN QUERY SELECT p.workspace_id,p.business_name,p.mfn_id,p.business_type,p.location FROM public.search_business_identities('signed_in','') p WHERE p.workspace_id<>_ws AND ((_mode='name' AND p.business_name ILIKE '%'||_value||'%') OR (_mode='email' AND lower(trim(p.business_contact_email))=lower(trim(_value))) OR (_mode='phone' AND length(regexp_replace(_value,'[^0-9]','','g'))>=10 AND regexp_replace(p.business_contact_phone,'[^0-9]','','g')=regexp_replace(_value,'[^0-9]','','g'))) ORDER BY p.business_name LIMIT 20; END $$;
CREATE OR REPLACE FUNCTION public.list_network_providers(_search text DEFAULT NULL,_service_type text DEFAULT NULL,_county text DEFAULT NULL,_city text DEFAULT NULL,_zip text DEFAULT NULL,_medical_delivery boolean DEFAULT NULL,_accepting boolean DEFAULT NULL,_saved_only boolean DEFAULT false) RETURNS TABLE(workspace_id uuid,business_name text,mfn_id text,description text,business_contact_email text,business_contact_phone text,service_types text[],counties text[],cities text[],zips text[],hours text,medical_delivery boolean,accepting_connections boolean,is_saved boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT b.workspace_id,b.business_name,b.mfn_id,b.description,b.business_contact_email,b.business_contact_phone,b.service_types,b.counties,b.cities,p.zips,p.hours,b.medical_delivery,b.accepting_connections,EXISTS(SELECT 1 FROM public.saved_network_providers s WHERE s.user_id=auth.uid() AND s.provider_workspace_id=b.workspace_id)
 FROM public.search_business_identities('signed_in',coalesce(_search,'')) b JOIN public.provider_network_profiles p ON p.workspace_id=b.workspace_id JOIN public.workspaces w ON w.id=b.workspace_id WHERE b.business_type='provider' AND w.provider_verified AND (coalesce(_service_type,'')='' OR _service_type=ANY(b.service_types)) AND (coalesce(_county,'')='' OR _county=ANY(b.counties)) AND (coalesce(_city,'')='' OR _city=ANY(b.cities) OR _city=p.location_city) AND (coalesce(_zip,'')='' OR _zip=ANY(p.zips)) AND (_medical_delivery IS NULL OR b.medical_delivery=_medical_delivery) AND (_accepting IS NULL OR b.accepting_connections=_accepting) AND (NOT _saved_only OR EXISTS(SELECT 1 FROM public.saved_network_providers s WHERE s.user_id=auth.uid() AND s.provider_workspace_id=b.workspace_id)) $$;
CREATE OR REPLACE FUNCTION public.network_public_service_centers() RETURNS TABLE(workspace_id uuid,lat double precision,lng double precision,radius_miles integer,city text,county text,zip text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.workspace_id,p.public_center_lat,p.public_center_lng,p.service_radius_miles,p.location_city,p.location_county,p.location_zip FROM public.provider_network_profiles p JOIN public.list_network_providers() b ON b.workspace_id=p.workspace_id $$;
CREATE OR REPLACE FUNCTION public.save_account_relationship_preferences(_ws uuid,_kind text,_target uuid,_name text,_confirmed boolean,_source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person text;account text;old_record jsonb; BEGIN
 IF NOT public.can_manage_account_connections(_ws) OR _confirmed IS DISTINCT FROM true OR _kind NOT IN ('referral','preferred') OR _source NOT IN ('onboarding','settings') OR length(coalesce(_name,''))>200 OR (SELECT account_type FROM public.workspaces WHERE id=_ws)='provider' THEN RAISE EXCEPTION 'Relationship update unavailable'; END IF;
 PERFORM 1 FROM public.workspaces WHERE id=_ws FOR UPDATE;
 IF _target IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.search_business_identities('signed_in','') b WHERE b.workspace_id=_target AND (_kind='referral' OR b.business_type='provider')) THEN RAISE EXCEPTION 'Opted-in business unavailable'; END IF;
 SELECT mfn_id INTO person FROM public.user_profiles WHERE user_id=auth.uid(); SELECT mfn_id INTO account FROM public.workspaces WHERE id=_ws; SELECT to_jsonb(r) INTO old_record FROM public.account_relationship_preferences r WHERE workspace_id=_ws;
 INSERT INTO public.account_relationship_preferences(workspace_id,updated_by,person_mfn_id,workspace_mfn_id,source) VALUES(_ws,auth.uid(),person,account,_source) ON CONFLICT DO NOTHING;
 IF _kind='referral' THEN UPDATE public.account_relationship_preferences SET referral_workspace_id=_target,referral_name=nullif(trim(_name),''),updated_by=auth.uid(),person_mfn_id=person,workspace_mfn_id=account,source=_source,updated_at=now() WHERE workspace_id=_ws;
 ELSE UPDATE public.account_relationship_preferences SET preferred_provider_id=_target,updated_by=auth.uid(),person_mfn_id=person,workspace_mfn_id=account,source=_source,updated_at=now() WHERE workspace_id=_ws; END IF;
 INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,_kind||'_confirmed',auth.uid(),person,account,jsonb_build_object('previous',old_record,'target',_target,'source',_source)); END $$;
ALTER TABLE public.ride_requests ADD COLUMN patient_workspace_id uuid REFERENCES public.workspaces(id), ADD COLUMN patient_workspace_mfn_id text, ADD COLUMN creator_person_mfn_id text, ADD COLUMN originating_workspace_mfn_id text;
CREATE FUNCTION public.patient_request_link_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE source_type text; BEGIN
 IF TG_OP='UPDATE' THEN IF NEW.patient_workspace_id IS DISTINCT FROM OLD.patient_workspace_id OR NEW.patient_workspace_mfn_id IS DISTINCT FROM OLD.patient_workspace_mfn_id OR NEW.creator_person_mfn_id IS DISTINCT FROM OLD.creator_person_mfn_id OR NEW.originating_workspace_mfn_id IS DISTINCT FROM OLD.originating_workspace_mfn_id THEN RAISE EXCEPTION 'Patient linkage and attribution are immutable'; END IF; RETURN NEW; END IF;
 SELECT account_type INTO source_type FROM public.workspaces WHERE id=NEW.workspace_id;
 IF source_type='private_pay' AND NEW.patient_workspace_id IS NULL THEN NEW.patient_workspace_id:=NEW.workspace_id; END IF;
 IF NEW.patient_workspace_id IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id JOIN public.user_profiles p ON p.user_id=m.user_id JOIN auth.users u ON u.id=m.user_id WHERE w.id=NEW.patient_workspace_id AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Verified patient account unavailable'; END IF;
 IF NEW.workspace_id IS DISTINCT FROM NEW.patient_workspace_id AND (source_type NOT IN ('provider','facility','hospital') OR NOT EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.workspace_a=least(NEW.workspace_id,NEW.patient_workspace_id) AND c.workspace_b=greatest(NEW.workspace_id,NEW.patient_workspace_id))) THEN RAISE EXCEPTION 'Explicit accepted patient connection required'; END IF;
 SELECT mfn_id INTO NEW.patient_workspace_mfn_id FROM public.workspaces WHERE id=NEW.patient_workspace_id;
 END IF;
 SELECT mfn_id INTO NEW.creator_person_mfn_id FROM public.user_profiles WHERE user_id=coalesce(NEW.actor_user_id,NEW.requester_user_id); SELECT mfn_id INTO NEW.originating_workspace_mfn_id FROM public.workspaces WHERE id=NEW.workspace_id; RETURN NEW; END $$;
CREATE TRIGGER zz_patient_request_link_guard BEFORE INSERT OR UPDATE ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.patient_request_link_guard();
CREATE FUNCTION public.patient_request_access(_request uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.ride_requests r JOIN public.workspaces w ON w.id=coalesce(r.patient_workspace_id,r.workspace_id) JOIN public.workspace_members m ON m.workspace_id=w.id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE r.id=_request AND NOT r.is_test AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND (r.patient_workspace_id=w.id OR (r.patient_workspace_id IS NULL AND r.requester_user_id=auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.patient_request_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.patient_request_access(uuid) TO authenticated;
CREATE FUNCTION public.list_linked_patient_accounts(_ws uuid) RETURNS TABLE(workspace_id uuid,display_name text,mfn_id text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_account_connections(_ws) OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND account_type IN ('provider','facility','hospital')) THEN RETURN; END IF; RETURN QUERY SELECT w.id,w.display_name,w.mfn_id FROM public.account_business_connections c JOIN public.workspaces w ON w.id=CASE WHEN c.workspace_a=_ws THEN c.workspace_b ELSE c.workspace_a END WHERE _ws IN (c.workspace_a,c.workspace_b) AND c.active AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id JOIN auth.users u ON u.id=m.user_id WHERE m.workspace_id=w.id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND u.email_confirmed_at IS NOT NULL); END $$;
REVOKE ALL ON FUNCTION public.list_linked_patient_accounts(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_linked_patient_accounts(uuid) TO authenticated;
CREATE FUNCTION public.patient_request_snapshot(_request uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.ride_requests;t public.trips;safe jsonb;events jsonb;payments jsonb;provider_name text; BEGIN
 IF NOT public.patient_request_access(_request) THEN RETURN NULL; END IF; SELECT * INTO r FROM public.ride_requests WHERE id=_request; SELECT * INTO t FROM public.trips WHERE ride_request_id=r.id ORDER BY created_at DESC LIMIT 1;
 SELECT coalesce(jsonb_agg(jsonb_build_object('action',e.to_state,'at',e.created_at) ORDER BY e.created_at),'[]'::jsonb) INTO events FROM public.request_status_events e WHERE e.ride_request_id=r.id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('reference',p.id,'amountCents',p.amount_cents,'status',p.status,'createdAt',p.created_at,'updatedAt',p.updated_at) ORDER BY p.created_at DESC),'[]'::jsonb) INTO payments FROM public.trip_payments p WHERE p.payer_user_id=auth.uid() AND (p.ride_request_id=r.id OR p.trip_id=t.id);
 IF t.network_provider_workspace_id IS NOT NULL THEN SELECT display_name INTO provider_name FROM public.workspaces WHERE id=t.network_provider_workspace_id; ELSIF coalesce(t.assigned_to,r.assigned_provider_id) IS NOT NULL THEN SELECT w.display_name INTO provider_name FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id WHERE m.user_id=coalesce(t.assigned_to,r.assigned_provider_id) AND m.role='owner' AND w.account_type='provider' AND w.status='active' LIMIT 1; END IF;
 SELECT jsonb_object_agg(key,value) INTO safe FROM jsonb_each(to_jsonb(r)) WHERE key=ANY(ARRAY['id','mfn_id','trip_kind','transport_type','trip_type','created_at','pickup_date','pickup_time','appointment_time','pickup_address','pickup_address_details','pickup_city','pickup_zip','dropoff_address','dropoff_city','dropoff_zip','round_trip','return_date','return_pickup_time','return_dropoff_time','return_pickup_building','return_pickup_suite','additional_stops','service_level','needs_wheelchair','needs_assistance_to_vehicle','patient_first_name','patient_last_name','patient_phone','patient_email','delivery_item_type','delivery_signature_required','delivery_instructions']);
 RETURN jsonb_build_object('request',safe,'status',coalesce(t.status,r.lifecycle_state,r.status),'tripId',t.id,'tripNumber',t.display_id,'providerName',provider_name,'source',CASE WHEN r.patient_workspace_id=r.workspace_id OR (r.patient_workspace_id IS NULL AND r.requester_user_id=auth.uid()) THEN 'Created by patient' WHEN (SELECT account_type FROM public.workspaces WHERE id=r.workspace_id)='provider' THEN 'Created by provider' ELSE 'Created by facility' END,'events',jsonb_build_array(jsonb_build_object('action','received','at',r.created_at))||events||CASE WHEN t.completed_at IS NOT NULL THEN jsonb_build_array(jsonb_build_object('action','completed','at',t.completed_at)) ELSE '[]'::jsonb END,'payments',payments,'scheduledAt',t.scheduled_start_time,'driverAssigned',t.driver_id IS NOT NULL AND t.status IN ('assigned','in_progress','completed'),'invoice',NULL); END $$;
REVOKE ALL ON FUNCTION public.patient_request_snapshot(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.patient_request_snapshot(uuid) TO authenticated;
CREATE FUNCTION public.list_patient_requests() RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.patient_request_snapshot(r.id) FROM public.ride_requests r WHERE public.patient_request_access(r.id) ORDER BY r.created_at DESC LIMIT 500 $$;
REVOKE ALL ON FUNCTION public.list_patient_requests() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.list_patient_requests() TO authenticated;
COMMENT ON COLUMN public.ride_requests.patient_workspace_id IS 'Explicit immutable patient-account attachment; accepted connection is required for business-created requests. Never backfilled by names or contacts. Patient projections use scoped RPCs, not broader table RLS.';